// Parity check of the standalone umT5-XXL tokenizer (src/umt5/tokenizer.ts and the shared layer
// src/text/t5-tokenizer.ts) against the Python reference. Needs neither a GPU nor real assets (when the
// real asset is present, the check also runs over the full vocabulary).
//
// The fixture `umt5/tokenizer-cases.json` is generated by the recipe
// `tools/export-recipes/wan/umt5_xxl_tokenizer.py` from the pin of upstream `google/umt5-xxl`. It holds
//  - the expectation per case (boundaries, multilingual + random). An id sequence when accepted, a reason when
//    rejected. **The reference id sequence comes from AutoTokenizer of transformers 5.14.1**, and accepted cases
//    also carry the id sequence of the tokenizer.json path (the two paths were checked to agree at generation
//    time — here too the result is compared with both). No preprocessing — the text is passed as is
//  - the **subset** of the vocabulary needed to reproduce them (the substrings of every case's fragments — the
//    lattice comes out the same as with the full vocabulary)
//
// One behaviour is pinned: "the same string yields the same id sequence as upstream, or is rejected for the
// same reason". Alongside, it checks the rejections of the asset reader, and that Wan (which runs the same
// tokenizer after preprocessing) never hits the whitespace rejection.

import { readTextFile } from "@karume/test-support/fs";
import { test } from "vite-plus/test";
import { assert, assertEquals, assertInstanceOf, assertThrows } from "@std/assert";
import { ModelInputError } from "../src/errors.ts";
import { type CodeRanges, inCodeRanges, parseCodeRanges } from "../src/text/code-ranges.ts";
import type { T5Tables, T5VocabEntry } from "../src/text/t5-tokenizer.ts";
import { UMT5_MAX_LENGTH, UMT5_MIN_TOKENS } from "../src/umt5/relative-position.ts";
import {
  parseUmt5TokenizerAsset,
  UMT5_TOKENIZER_FORMAT,
  Umt5Tokenizer,
} from "../src/umt5/tokenizer.ts";
import { PromptCleanError } from "../src/wan/text/prompt-clean.ts";
import { WAN_TOKENIZER_FORMAT } from "../src/wan/text/tokenizer.ts";
import { mirrorPresent, mirrorRoot, readMirrorAsset } from "./helpers/mirror.ts";
import { wanParityEncoder } from "./helpers/wan-parity-encoder.ts";

type FixtureCase = {
  readonly id: string;
  readonly why: string;
  readonly text: string;
  readonly ids?: number[];
  readonly tokenizerJsonIds?: number[];
  readonly reject?: string;
};

type Fixture = {
  readonly assetFormat: string;
  readonly maxLength: number;
  readonly minTokens: number;
  readonly t5: {
    readonly addedTokens: [string, number][];
    readonly unkId: number;
    readonly eosId: number;
    readonly minScore: number;
    readonly maxTokenLength: number;
    readonly space: unknown;
    readonly vocab: [string, number, number][];
  };
  readonly cases: FixtureCase[];
};

const fixture = JSON.parse(
  await readTextFile(new URL("./fixtures/umt5/tokenizer-cases.json", import.meta.url)),
) as Fixture;

const space: CodeRanges = parseCodeRanges(fixture.t5.space, "space");
const t5Tables: T5Tables = {
  vocab: new Map<string, T5VocabEntry>(
    fixture.t5.vocab.map(([token, id, score]) => [token, { id, score }]),
  ),
  // MUST: not derived from the subset — the unknown-node score and the search width come from the
  // **full** vocabulary.
  minScore: fixture.t5.minScore,
  maxTokenLength: fixture.t5.maxTokenLength,
  unkId: fixture.t5.unkId,
  eosId: fixture.t5.eosId,
  addedTokens: new Map(fixture.t5.addedTokens),
  space,
  maxLength: fixture.maxLength,
};
const tokenizer = new Umt5Tokenizer(t5Tables);

/** Rejection reason → message marker (per reason, a spelling that no other reason's message contains). */
const REJECT_MARKERS: Record<string, string> = {
  oov: "not in the vocabulary",
  "too-long": `upper bound ${UMT5_MAX_LENGTH}`,
  "too-short": `minimum ${UMT5_MIN_TOKENS}`,
  "added-token": "special token",
  metaspace: "U+2581",
  whitespace: "U+0020",
};

/**
 * The real asset (full vocabulary — when present, the check also runs independently of the subset
 * lattice): the tokenizer the umT5 distribution ships (ADR 0139 decision 1).
 */
const UMT5_MIRROR = mirrorRoot("karume-umt5-xxl");
const mirrorAsset = mirrorPresent(UMT5_MIRROR)
  ? new TextDecoder().decode(await readMirrorAsset(UMT5_MIRROR, "tokenizer"))
  : undefined;
if (mirrorAsset === undefined) {
  console.warn(
    `[karume] the mirror ${UMT5_MIRROR.pathname} is absent (or not karume/5), so the umT5 full-vocabulary check is ` +
      "SKIPPED (fetch the karume-umt5-xxl distribution into models/)",
  );
}

const caseById = (id: string): FixtureCase => {
  const found = fixture.cases.find((entry) => entry.id === id);
  if (found === undefined) throw new Error(`the fixture has no case ${id}`);
  return found;
};

/** Expects a rejection (a `ModelInputError` carrying the reason's marker). */
const assertRejected = (run: () => unknown, reason: string, message?: string): ModelInputError => {
  const marker = REJECT_MARKERS[reason];
  assert(marker !== undefined, `unknown rejection reason ${reason}`);
  return assertThrows(run, ModelInputError, marker, message);
};

// ---- The fixture itself -----------------------------------------------------

test("the fixture is non-empty and carries the asset format, the bounds and every outcome", () => {
  // Kept first. If a misread or a failed generation leaves cases empty, the loops below run zero times
  // and a "green but checking nothing" state passes silently.
  assert(fixture.cases.length >= 60, `case count ${fixture.cases.length} is too small`);
  assertEquals(fixture.assetFormat, UMT5_TOKENIZER_FORMAT);
  assertEquals(fixture.maxLength, UMT5_MAX_LENGTH);
  assertEquals(fixture.minTokens, UMT5_MIN_TOKENS);
  assertEquals(fixture.t5.addedTokens.length, 304, "umT5 has 304 added tokens");
  const reasons = new Set(fixture.cases.map((entry) => entry.reject ?? "accepted"));
  for (const reason of ["accepted", ...Object.keys(REJECT_MARKERS)]) {
    assert(reasons.has(reason), `no case with outcome ${reason}`);
  }
});

for (const testCase of fixture.cases) {
  test(`parity [${testCase.id}] ${testCase.why}`, () => {
    if (testCase.ids !== undefined) {
      const ids = tokenizer.tokenize(testCase.text);
      assertInstanceOf(ids, Int32Array);
      assertEquals([...ids], testCase.ids, "id sequence of transformers 5.14.1");
      assertEquals([...ids], testCase.tokenizerJsonIds, "id sequence of the tokenizer.json path");
      return;
    }
    assertRejected(() => tokenizer.tokenize(testCase.text), testCase.reject as string);
  });
}

// ---- Boundaries (what the fixture cases actually exercise) -------------------

test("upper bound: exactly 512 tokens is accepted, 513 is rejected (no silent truncation)", () => {
  const max = tokenizer.tokenize(caseById("max-512").text);
  assertEquals(max.length, UMT5_MAX_LENGTH);
  assertEquals(max.at(-1), fixture.t5.eosId, "ends with </s>");
  assertRejected(() => tokenizer.tokenize(caseById("over-513").text), "too-long");
});

test("lower bound: 2 tokens is accepted, the empty string (only </s>) is rejected", () => {
  assertEquals(tokenizer.tokenize("cat").length, UMT5_MIN_TOKENS);
  assertRejected(() => tokenizer.tokenize(""), "too-short");
});

test("whitespace: U+0020 at the start and between words is accepted, a trailing U+0020 and any whitespace other than U+0020 is rejected", () => {
  assertEquals(
    [...tokenizer.tokenize("  a cat")],
    caseById("leading-spaces").ids,
    "leading U+0020",
  );
  assertEquals(
    [...tokenizer.tokenize("a   cat  sits")],
    caseById("inner-spaces").ids,
    "consecutive U+0020 between words",
  );
  assertRejected(() => tokenizer.tokenize("a cat "), "whitespace", "trailing U+0020");
  assertRejected(() => tokenizer.tokenize("   "), "whitespace", "whitespace only");
  // The rejection message names the character to fix by code point (so a person can find an
  // invisible character).
  assertThrows(() => tokenizer.tokenize("猫　犬"), ModelInputError, "U+3000");
  assertThrows(() => tokenizer.tokenize("a\tcat"), ModelInputError, "U+0009");
});

test("rejection order: added token → ▁ right after whitespace → whitespace → out of vocabulary (the same order as the recipe's generation)", () => {
  // Each input carries two violations, and the check is that it fails on the earlier reason (if the
  // order were swapped, only the reason would change).
  assertRejected(() => tokenizer.tokenize("a </s> ▁b\t"), "added-token");
  assertRejected(() => tokenizer.tokenize("a ▁b\tcat"), "metaspace");
  assertRejected(() => tokenizer.tokenize("a\t\u{2000b}"), "whitespace");
});

test("the rejection message carries the caller's label, and a lone surrogate is rejected as an input error", () => {
  assertThrows(() => tokenizer.tokenize("\u{2000b}", "negative"), ModelInputError, "negative:");
  assertThrows(() => tokenizer.tokenize("a\ud800b"), ModelInputError, "surrogate");
});

// ---- The Wan path (the same tokenizer after preprocessing) --------------------

/** The whitespace set of Wan's parity fixture (the Wan asset's `space` — the table of the tokenizer run after preprocessing). */
const wanSpace: CodeRanges = parseCodeRanges(
  (
    JSON.parse(await readTextFile(new URL("./fixtures/wan-text/parity.json", import.meta.url))) as {
      readonly t5: { readonly space: unknown };
    }
  ).t5.space,
  "wan.space",
);

test("Wan: after preprocessing, neither whitespace other than U+0020 nor trailing whitespace remains (the whitespace rejection never fires)", () => {
  // The whitespace rejection of `Umt5Tokenizer` is meant for the path without preprocessing; Wan runs the
  // mirror of `prompt_clean` before passing the text to the same tokenizer. If preprocessing folds every
  // character of the asset's whitespace set into one U+0020 and strips both ends, Wan's accepted set is the
  // same as before the sharing (every character of the Wan asset's whitespace table is tried).
  const encoder = wanParityEncoder();
  const plainOnly = (text: string): boolean =>
    Array.from(text).every(
      (ch) => ch === " " || !inCodeRanges(wanSpace, ch.codePointAt(0) as number),
    );
  let checked = 0;
  for (const [start, end] of wanSpace) {
    for (let cp = start; cp <= end; cp += 1) {
      const ch = String.fromCodePoint(cp);
      for (const text of [`a${ch}b`, `a${ch}`, `${ch}a`, `a ${ch} `, `${ch}`]) {
        let cleaned: string;
        try {
          cleaned = encoder.clean(text);
        } catch (error) {
          // Characters the preprocessing rejects (such as the C1 U+0085) never reach the tokenizer.
          assertInstanceOf(error, PromptCleanError);
          continue;
        }
        assert(plainOnly(cleaned), `${JSON.stringify(text)} → ${JSON.stringify(cleaned)}`);
        assert(!cleaned.endsWith(" "), `${JSON.stringify(text)} → ${JSON.stringify(cleaned)}`);
        checked += 1;
      }
    }
  }
  assert(checked >= 100, `too few inputs checked (${checked})`);
});

// ---- Reading the asset (external boundary) -----------------------------------

/** The smallest asset JSON (6 vocabulary rows). */
const minimalAsset = (patch: Record<string, unknown> = {}): Record<string, unknown> => ({
  format: UMT5_TOKENIZER_FORMAT,
  maxLength: 512,
  unkId: 2,
  eosId: 1,
  addedTokens: [
    ["<pad>", 0],
    ["</s>", 1],
    ["<s>", 2],
    ["<unk>", 3],
  ],
  space: [
    [0x09, 0x0d],
    [0x20, 0x20],
  ],
  vocabText: "<pad>\n</s>\n<s>\n<unk>\n▁cat\n▁",
  scores: [0, 0, 0, 0, -1, -2],
  ...patch,
});

test("parseUmt5TokenizerAsset: a tokenizer built from the asset JSON can encode", () => {
  const tiny = new Umt5Tokenizer(parseUmt5TokenizerAsset(minimalAsset()));
  assertEquals(tiny.maxLength, 512);
  assertEquals([...tiny.tokenize("cat cat")], [4, 4, 1]);
  assertThrows(() => tiny.tokenize("dog"), ModelInputError, "not in the vocabulary");
  assertThrows(() => tiny.tokenize("cat\tcat"), ModelInputError, "U+0009");
});

test("parseUmt5TokenizerAsset: an unknown format version is not read (nor is the Wan asset's format)", () => {
  for (const format of ["karume-umt5-tokenizer/2", WAN_TOKENIZER_FORMAT]) {
    assertThrows(
      () => parseUmt5TokenizerAsset(minimalAsset({ format })),
      Error,
      `cannot read format ${format}`,
    );
  }
  assertThrows(
    () => parseUmt5TokenizerAsset(minimalAsset({ format: undefined })),
    Error,
    "tokenizer.format",
  );
  assertThrows(() => parseUmt5TokenizerAsset("tokenizer"), Error, "not an object");
});

test("parseUmt5TokenizerAsset: a broken table fails (a plain Error, not an input error)", () => {
  const rejected: readonly [string, Record<string, unknown>, string][] = [
    ["wrong number of scores", { scores: [0, 0, 0, 0, -1] }, "the length of scores"],
    [
      "duplicate vocabulary row",
      { vocabText: "<pad>\n</s>\n<s>\n<unk>\n▁cat\n▁cat" },
      "a duplicate is a corrupt distribution",
    ],
    ["non-finite score", { scores: [0, 0, 0, 0, -1, Number.NaN] }, "finite"],
    [
      "overlapping whitespace table",
      {
        space: [
          [0x09, 0x20],
          [0x20, 0x20],
        ],
      },
      "overlaps",
    ],
    ["no maximum length", { maxLength: undefined }, "maxLength"],
    ["eos outside the vocabulary", { eosId: 6 }, "eosId"],
    [
      "added token id past the vocabulary",
      { addedTokens: [["<x>", 6]] },
      "which is >= the vocabulary row count 6",
    ],
    [
      "added token id disagrees with its vocabulary row",
      { addedTokens: [["<s>", 3]] },
      "which disagrees with vocabulary row 2",
    ],
  ];
  for (const [label, patch, message] of rejected) {
    const error = assertThrows(
      () => parseUmt5TokenizerAsset(minimalAsset(patch)),
      Error,
      message,
      label,
    );
    assert(
      !(error instanceof ModelInputError),
      `an asset inconsistency is not an input error: ${label}`,
    );
  }
});

// ---- Comparison on the real asset (full vocabulary) ---------------------------

test.skipIf(mirrorAsset === undefined)(
  "real asset: a tokenizer built from the full-vocabulary asset reaches the same outcome on every fixture case",
  () => {
    // The fixture's vocabulary is a subset (the substrings of the fragments), so this checks that reading the
    // asset (256K rows) and the full-vocabulary lattice also give the same id sequences / rejections.
    const full = new Umt5Tokenizer(parseUmt5TokenizerAsset(JSON.parse(mirrorAsset as string)));
    assertEquals(full.maxLength, UMT5_MAX_LENGTH);
    for (const testCase of fixture.cases) {
      if (testCase.ids !== undefined) {
        assertEquals([...full.tokenize(testCase.text)], testCase.ids, testCase.id);
      } else {
        assertRejected(() => full.tokenize(testCase.text), testCase.reject as string, testCase.id);
      }
    }
  },
);
